def ref(inp):
    # Model: a schedule is an ordered sequence of shipments, each carrying at most K orders.
    # Each shipment's day is the earliest feasible day: max(largest T in the batch, previous day + X).
    # Dissatisfaction is nondecreasing in each shipment day, so earliest is optimal for a fixed sequence.
    # Batches are taken as contiguous blocks of the sorted order and shipped in that order
    # (standard exchange argument: swapping orders between batches never breaks feasibility or raises cost).
    t = inp.split()
    n, k, x = int(t[0]), int(t[1]), int(t[2])
    T = [int(v) for v in t[3:3 + n]]

    @lru_cache(maxsize=None)
    def f(i, last):
        if i == n:
            return 0
        best = None
        for j in range(i + 1, min(i + k, n) + 1):
            if last is None:
                S = T[j - 1]
            else:
                S = max(T[j - 1], last + x)
            cost = sum(S - T[m] for m in range(i, j)) + f(j, S)
            if best is None or cost < best:
                best = cost
        return best

    return str(f(0, None))
