    n, k, x = (int(v) for v in lines[0].split())
    t = [int(v) for v in lines[1].split()]
    best = None
    # Enumerate every assignment of orders to shipment labels 0..m-1.
    # Label j means shipment j (in shipping order). Each label must be used,
    # and each shipment holds at most k orders.
    for m in range(1, n + 1):
        for f in product(range(m), repeat=n):
            groups = [[] for _ in range(m)]
